/// <summary>
/// PaffH 05.11.24
/// </summary>
protected void new()
{
    maintainRelayContract = new PALabelMaintainRelayContract();
}

/// <summary>
/// PaffH 05.11.24
/// </summary>
/// <returns>NDXAzureRelayTransferPALabel</returns>
public static NDXAzureRelayTransferPALabel construct()
{
    return new NDXAzureRelayTransferPALabel();
}

/// <summary>
/// PaffH 05.11.24
/// </summary>
/// <param name = "_contract">IHostContract</param>
public void initMaintainRelayContract(IHostContract _contract)
{
    super(_contract);
}

/// <summary>
/// PaffH 15.10.24
/// </summary>
/// <param name = "_nDXProdIdentControlPanel">NDXProdIdentControlPanel</param>
/// <returns>NDXAzureRelayTransferPALabel</returns>
//public NDXAzureRelayTransferPALabel addContractFromNDXProdIdentControlPanel(NDXProdIdentControlPanel _nDXProdIdentControlPanel)
public NDXAzureRelayTransferPALabel addContractFromNDXProdIdentControlPanel(List _nDXProdIdentControlPanelList)
{
    ListEnumerator listEnum = _nDXProdIdentControlPanelList.getEnumerator();
    while (listEnum.moveNext())
    {
        NDXProdIdentControlPanel nDXProdIdentControlPanel = listEnum.current();
        Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract contract =  NDXProdIdentControlPanel::fillContractFromRecord2(nDXProdIdentControlPanel);
        maintainRelayContract.AddContractToList(contract);
    }
    return this;
}

/// <summary>
/// PaffH 30.04.24
/// </summary>
/// <returns>NDXAzureRelayTransferPALabel</returns>
public NDXAzureRelayTransferPALabel getDataFromDialog()
{
    NDXProdIdentControlPanel nDXProdIdentControlPanel;

    Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract contract =  NDXProdIdentControlPanel::fillContractFromRecord2(nDXProdIdentControlPanel);
    maintainRelayContract.AddContractToList(contract);
    return this;
}

/// <summary>
/// PaffH 07.11.24
/// </summary>
/// <returns>ResponseLabelMaintainedContract</returns>
public Niedax.AzureServiceBus.Models.PALabel.ResponseLabelMaintainedContract getResponseFromRelay()
{
    azureRelaySender.fillRequest(maintainRelayContract);
    HttpResponseMessage response = azureRelaySender.SendMessage().GetAwaiter().GetResult();
    if (response.IsSuccessStatusCode && response.StatusCode != System.Net.HttpStatusCode::Conflict)
    {
        responseContract = azureRelaySender.contractFromResponseMessage(response) as ResponseLabelMaintainedContract;
    }
    else
    {
        throw Error(response.ReasonPhrase);
    }
    return responseContract;
}

/// <summary>
/// PaffH 30.04.24
/// modified: 07.11.24
/// get response (ResponseLabelMaintainedContract) from onPrem listener
/// </summary>
/// <returns>list with NDXAzureRelayTransferPALabel</returns>
public List getProdIdentControlPanelLines()
{
    List listContract = new List(Types::Class);
    this.getResponseFromRelay();
    Niedax.AzureServiceBus.Models.PALabel.NDXProdIdentControlPanelContract contract;
    if (responseContract)
    {
        IEnumerable enumerableList = responseContract.ProdIdentControlPanelLines;
        IEnumerator enumeratorList = enumerableList.GetEnumerator();
        while (enumeratorList.MoveNext())
        {
            contract = enumeratorList.Current;
            listContract.addEnd(contract);
        }
    }
    return listContract;
}
